from engine import *

PART5 = "Part 5. Safety, lessons and scenarios"
PART6 = "Part 6. Knowledge and AI"
ALL = ["Operator", "Engineer", "Reliability", "HSE", "Manager"]

def blocks():
    b = []
    # ------------------------------------------------------------------ 28 OPL Library
    b += [H1(28, "One Point Lesson Library", ALL, PART5,
             "A one point lesson (OPL) is a short sheet that teaches one thing about one machine. The library holds 56 sheets, with 83 scenarios that let you practise the lesson on the P&ID or in 3D."),
          FIG("p5_opl", "The One Point Lesson Library.",
              [(1, "**Lessons by class**: Basic Knowledge, Improvement and Trouble Case.", "^Lessons by class$"),
               (2, "**Lessons by discipline** and **Lessons by equipment**. Select a segment or a bar to filter.", "^Lessons by discipline$"),
               (3, "Filters for the equipment set and the classification.", "^All equipment sets$"),
               (4, "A lesson card with its number, title, key message, step count and date.", "^OPL-GA-1201A-01$"),
               (5, "**Open sheet** and **Simulate** for each lesson.", "^Open sheet$")], maxh=210),
          STEPS(["Filter by equipment set or classification, or select a segment on the charts.",
                 "Read the card. The first line of text states the lesson in one sentence.",
                 "Select **Open sheet** to read the full lesson.",
                 "Select **Simulate** to practise it. The number in brackets is the number of scenarios for the lesson."]),
          H2("The lesson sheet"),
          FIG("p5_opl_sheet", "An OPL sheet in the plant's standard layout.",
              [(1, "Switch between **OPL sheet** and **Scenario simulator**.", "^OPL sheet$"),
               (2, "Header: number, title, discipline, equipment, area, related interlock and P&ID reference.", "^ONE POINT LESSON"),
               (3, "The classification and the aspect code.", "^Classification:")], maxh=210),
          P("Each sheet follows the same order: purpose, safety precautions, the steps, the quantitative values to check and a troubleshooting table. The hazard note on the sheet states the fluid, pressure and temperature of the machine, and the precautions that apply before the work starts."),
          ]
    # ------------------------------------------------------------------ 29 OPL simulator
    b += [H1(29, "OPL scenario simulator", ALL, PART5,
             "The scenario simulator lets you practise a lesson without risk. You see the P&ID or the 3D model of the machine, you act in the field and at the panel, and the simulation shows what follows."),
          FIG("p5_sim2d", "A scenario on the P&ID.",
              [(1, "The scenarios of the lesson. Each has a name and a type: fault condition, incorrect practice or pre-start check.", "^Procedure$"),
               (2, "The story and the goal of the scenario.", "^Goal:"),
               (3, "**Reset**, **Show guidance**, and the **P&ID** and **3D view** switch.", "^3D view$"),
               (4, "Readings and the state of the interlock.", "^SEQ-1201"),
               (5, "**Field and panel actions** and the **Panel controls**.", "^Field and panel actions$")], maxh=210),
          STEPS(["Open a lesson and select **Scenario simulator**, or select **Simulate** on the lesson card.",
                 "Choose a scenario in the list. Read the story and the goal.",
                 "Select **Run** to start the simulation.",
                 "Select the field and panel actions in the order you think correct. Actions marked with a step number match a step of the lesson.",
                 "Select **Show guidance** if you need a hint. Select **Reset** to start the scenario again."]),
          H2("Switching to 3D"),
          P("Select **3D view** to see the same scenario on the 3D model. Rotate and zoom as in Chapter 14. The animation is the same as on the P&ID: flows stop, parts move and alarms change colour as the simulation runs."),
          FIG("p5_sim3d", "The same scenario in 3D.", maxh=210),
          NOTE("caution", "The simulator uses simulated values. It is a training aid and does not act on the plant. Panel controls such as **Apply interlock bypass (no permit)** exist to show the consequence of a wrong action."),
          ]
    # ------------------------------------------------------------------ 30 Scenarios
    b += [H1(30, "Scenarios and chain reaction", ["Operator", "Engineer", "Reliability", "HSE", "Manager"], PART5,
             "The Scenarios page shows how a failure on one unit spreads to the others. It also replays an OPL case or a work order on the P&ID. A third tab records the assumptions behind the numbers."),
          H2("Plant chain reaction"),
          FLOW("f_chain", [[("pill", "Choose the initiating event"), ("box", "Choose the equipment, or a utility loss"), ("box", "Choose the cause and the severity")],
                           [("box", "The model finds connected units upstream and downstream"), ("dia", "Does the unit stop?", ""), ("pill", "Read the units affected, the outage and the cost")]],
               "How the chain reaction is set up and read."),
          FIG("p5_scn", "The Plant chain reaction tab.",
              [(1, "The three tabs of the page.", "^Plant chain reaction$"),
               (2, "**Initiating event**: equipment or utility loss.", "^Initiating event$"),
               (3, "**Cause** and **Severity**: a unit trip or degraded operation.", "^Severity$"),
               (4, "**From predictive maintenance**: choose one of the forecast failures.", "^From predictive maintenance$")], maxh=200),
          STEPS(["Choose **Equipment** or **Utility loss** as the initiating event.",
                 "Choose the equipment set, or select a unit tile on the plant.",
                 "Choose a cause. For the compressor, the list shows the trips T1 to T6 with their set points.",
                 "Choose the severity: **Trip: unit stops** or **Degraded: about half output, no trip**.",
                 "Select **Play** to watch the failure spread. Use **Speed** to set the step from one minute to sixty minutes.",
                 "Read the result tiles: units tripped, units affected, the combined outage estimate and the maintenance cost estimate."]),
          FIG("p5_scn_run", "A chain reaction in progress.", maxh=210),
          H2("OPL and maintenance scenario"),
          P("This tab replays one case on the P&ID: a lesson scenario or a work order. The symptom, the cause and the action steps are shown beside the diagram, and the tags involved are highlighted."),
          FIG("p5_scn_opl", "The OPL and maintenance scenario tab.", maxh=170),
          H2("Assumptions register"),
          P("Every number on the page rests on an assumption, such as how long a unit takes to restart or how much a day of downtime costs. The register lists each assumption with its value and its source, so that you can judge how far to trust the result."),
          FIG("p5_scn_as", "The Assumptions register.", maxh=150),
          ]
    # ------------------------------------------------------------------ 31 Plot plan and hazard
    b += [H1(31, "Plot Plan and hazard simulator", ALL, PART5,
             "The Plot Plan shows the site layout to scale. The hazard simulator shows how a gas cloud, a fire or a blast would spread from a chosen unit, which units and routes are affected and how long it takes to reach a muster point."),
          H2("Site overview"),
          FIG("p5_plot", "The Plot Plan, Site overview.",
              [(1, "Switch between **Site overview** and **Hazard simulator**.", "^Site overview$"),
               (2, "Map layers: Areas, Heat map, Hazard zones, Muster and gates, Fire protection and Walkways.", "^Areas$"),
               (3, "The control room, muster points and gates.", "^CONTROL ROOM$"),
               (4, "**Walking distance from control room** and **Recorded breakdowns** by unit.", "^Walking distance from control room")], maxh=210),
          BUL(["Drag to pan and scroll to zoom. Footprints are to scale, in metres.",
               "Select a unit to see its location and send the operator to it. The route and the walking time are shown.",
               "Use **Heat map** to colour the units by the number of recorded breakdowns."]),
          NOTE("note", "Unit positions and footprints come from the plot plan drawings. The overlay layers for hazard zones, muster points, fire protection and walkways are approximate."),
          H2("Hazard simulator in 2D"),
          FIG("p5_haz2d", "The hazard simulator on the 2D plan.",
              [(1, "Choose the source unit, its fluid and the scenario: gas cloud, jet fire or pool fire.", "^Screening model$"),
               (2, "Hole size, wind speed, wind direction and weather.", "^Hole size$"),
               (3, "Shutdown mode and the operator reaction time.", "^Shutdown$"),
               (4, "**Play**, **Speed** and the time slider. **Ignite the cloud** sets the ignition time.", "^Play$"),
               (5, "Release figures and the cloud extent at 100, 50 and 25 percent of the lower flammable limit.", "^Effects$"),
               (6, "**Who and what is affected**, **Walk to muster** and **Barriers in this case**.", "^Who and what is affected$")], maxh=220),
          STEPS(["Select **Hazard simulator**.",
                 "Choose the source unit and the scenario.",
                 "Set the hole size, the wind speed, the wind direction and the weather.",
                 "Choose how the unit shuts down: automatic on gas alarm, manual by the operator, or fails to close. For a manual shutdown, set the operator reaction time.",
                 "Select **Play** or drag the time slider. The coloured zones show 25, 50 and 100 percent of the lower flammable limit (LFL).",
                 "Read **Who and what is affected** for the distance to each unit, building, muster point and gate.",
                 "Read **Walk to muster** to compare the routes. The better route is marked."]),
          H2("Hazard simulator in 3D"),
          P("Select **3D site** to see the cloud as a volume over the plant. Rotate the view to look at the cloud from the side or from above. The same controls apply."),
          FIG("p5_haz3d", "The hazard simulator in 3D.", maxh=210),
          NOTE("caution", "The simulator is a screening model. It supports planning and training. It does not replace a formal consequence study."),
          ]
    # ------------------------------------------------------------------ 32 AI Assistant
    b += [H1(32, "AI Assistant", ALL, PART6,
             "The AI Assistant answers questions in plain language from the documents, the drawings, the interlock logic, the lessons and the work orders. Each answer lists its sources and their approval status."),
          FIG("p6_ai", "An answer from the AI Assistant.",
              [(1, "**Scope**: all equipment sets or one set.", "^Scope$"),
               (2, "Your question and the answer, with numbered source tags.", "^What usually causes"),
               (3, "**Sources for the last answer** with revision and approval status.", "^Sources for the last answer$"),
               (4, "The question box and **Send**.", "^Send$")], maxh=210),
          H2("Asking a question"),
          STEPS(["Open **AI Assistant** in the sidebar.",
                 "Choose the **Scope**. A narrower scope gives a more precise answer.",
                 "Type a question in the box, or select one of the example questions.",
                 "Select **Send**.",
                 "Read the answer. Each statement carries a source number. Select a number to open the source.",
                 "Use **Export transcript** to save the conversation, or **Clear** to start again."]),
          H2("What you can ask"),
          TABLE(["Kind of question", "Example"],
                [["Procedure", "How is a mechanical seal leak on the hexane feed pump resolved?"],
                 ["Interlock", "What is the start permissive for the recycle gas compressor KC-4501?"],
                 ["Location", "Where is the cooling tower fan CT-7801 located?"],
                 ["Equipment facts", "What is the trip set point of the suction pressure low-low switch on the hexane feed pump?"],
                 ["Maintenance history", "What usually causes a mechanical seal leak on the hexane feed pump and how was it fixed?"],
                 ["Comparison and ranking", "Which equipment set has the highest failure risk now?"],
                 ["Calculation", "What is the MTBF of each equipment?"]],
                [24, 76]),
          FIG("p6_ai_rank", "A ranking question. The answer is computed from the maintenance history and says so.", maxh=170),
          H2("Why this answer"),
          P("Select **Why this answer** under an answer to see how it was built: the type of question the assistant recognised, the records it retrieved, their approval status and the check of every number against the sources."),
          FIG("p6_ai_why", "The Why this answer panel.", maxh=210),
          H2("Questions the assistant will not answer"),
          P("The assistant refuses requests to bypass, defeat or override a trip, an interlock, an alarm or a permissive. The refusal happens in the page, and the request is never sent to an AI service. The assistant points to the approved procedure instead."),
          FIG("p6_ai_refuse", "A request to bypass a trip is refused.", maxh=170),
          H2("Feedback"),
          P("Use the feedback links under an answer to mark it **Incomplete** or **Wrong**. The report goes to the review queue in Knowledge Studio (Chapter 34), where a person with approval rights can correct the knowledge."),
          ]
    # ------------------------------------------------------------------ 33 How answers are produced
    b += [H1(33, "How answers are produced", ALL, PART6,
             "This chapter explains what happens between a question and an answer, so that you know how far to trust it."),
          FLOW("f_ai", [[("pill", "Your question"), ("warn", "Bypass request? Refuse"), ("box", "Recognise the kind of question")],
                        [("db", "Search the knowledge base"), ("box", "Rank by match and approval status"), ("ai", "Compose the answer from the top records")],
                        [("box", "Check every number against the sources"), ("box", "Set the confidence level"), ("pill", "Show the answer and its sources")]],
               "The path from question to answer."),
          STEPS(["**Safety check.** A request to bypass a protective function is refused at once.",
                 "**Recognition.** The assistant decides whether the question is about a procedure, an interlock, a location, a number, a history or a ranking.",
                 "**Search.** The knowledge base is searched by keyword and by meaning. Typed facts and computed figures, such as MTBF, are read directly from the data.",
                 "**Ranking.** Records are ranked by how well they match and by their approval status.",
                 "**Composition.** The answer is written from the top records. When an administrator has connected an AI service, it words the answer from those records. Otherwise a built-in method writes it.",
                 "**Verification.** Every number in the answer is compared with the sources. A statement without support is stated as a gap.",
                 "**Delivery.** The answer is shown with numbered sources, their revision and status, and a confidence level."]),
          H2("How approval status affects ranking"),
          TABLE(["Status", "Weight in the ranking"],
                [["Approved", "1.0"], ["Not stated", "0.8"], ["In review", "0.7"], ["Draft", "0.55"], ["Superseded", "0.35"], ["Rejected", "Left out"]],
                [50, 50]),
          NOTE("role", "Operators see only approved items in the typed facts. Engineers, Reliability, HSE and Managers can also see items that are in review."),
          NOTE("caution", "A low confidence level, or a statement that the data has a gap, is a result. Check the source document or ask a colleague before you act."),
          ]
    # ------------------------------------------------------------------ 34 Knowledge Studio
    b += [H1(34, "Knowledge Studio", ALL, PART6,
             "Knowledge Studio is where plant knowledge is added, reviewed and approved. Approved items are searchable at once, and the assistant cites them with their revision and status."),
          FIG("p6_ks", "Knowledge Studio, Overview tab.",
              [(1, "The eight tabs.", "^Overview$"),
               (2, "Counts: indexed chunks, items added by users, waiting for review, approved and open feedback.", "^Indexed knowledge chunks$"),
               (3, "Four ways to add knowledge.", "^Ingest a document$"),
               (4, "**Backup and transfer**: export or import the user knowledge.", "^Backup and transfer$")], maxh=200),
          FLOW("f_appr", [[("pill", "Write a draft"), ("box", "Save and submit for review"), ("dia", "Approver reviews", "")],
                          [("warn", "Rejected: returns to the author"), ("pill", "Approved: searchable, cited by the assistant"), ("db", "Every step is written to the audit trail")]],
               "The approval workflow."),
          H2("Ingest documents"),
          P("The ingestion wizard turns a file or pasted text into searchable knowledge in six steps: **Source**, **Kind**, **Structure**, **Details**, **Checks** and **Create**."),
          FIG("p6_ks_ingest", "The ingestion wizard, first step.",
              [(1, "The six steps of the wizard.", "^Source$"),
               (2, "Choose files, or drop them on the box. The wizard reads text, CSV, JSON, HTML, PDF with a text layer, Excel and Word files.", "^Upload files$"),
               (3, "Or paste text or a table, with a title.", "^Paste text or a table$"),
               (4, "Option to let the AI read new documents. It is available only when the shared database is online.", "^Let the AI read new documents$")], maxh=180),
          STEPS(["Add the file or paste the text, then select **Next**.",
                 "Choose the kind of document: for example an SOP, a datasheet, a P&ID, an interlock sheet, a maintenance log, an instrument list, an OPL, an incident report or notes.",
                 "Check the structure the wizard found: headings, steps, tables and tags.",
                 "Confirm the details: title, equipment set, revision and date.",
                 "Read the checks. They flag missing tags, an unknown equipment set and duplicate content.",
                 "Select **Create**. The item is saved as a draft and appears in the Library."]),
          NOTE("tip", "Secrets and personal numbers are masked before any text is sent to an AI service."),
          H2("Capture knowledge"),
          P("Three forms record what people know. **Tacit knowledge** records an expert's symptom, cause, action and caution for an asset. **Lesson learned** records what changed after an incident. **Failure report** goes into the failure memory and can also create a work order."),
          FIG("p6_ks_cap", "The tacit knowledge form.",
              [(1, "Choose the type of record.", "^Tacit knowledge$"),
               (2, "Title, equipment set, component and tags.", "^Title$"),
               (3, "Symptom, likely cause, action and caution.", "^Symptom or situation$"),
               (4, "**Save as draft** or **Save and submit for review**.", "^Save and submit for review$")], maxh=180),
          H2("Library"),
          P("The Library lists every item added by users with its identifier, title, type, asset, revision, status, author and date. Use the filter box to find an item. Select an item to read it. The buttons on each row depend on the status: **Submit** for a draft, **Approve** and **Reject** for an item in review, **Withdraw** for an approved item and **Reopen as draft** for a rejected or withdrawn one. Drafts can also be edited or deleted."),
          FIG("p6_ks_lib", "The Library.", maxh=150),
          H2("Review queue"),
          P("The Review queue lists the items waiting for approval and the answer feedback reported by users. Operators can draft and submit. Engineers, Reliability, HSE and Managers can approve. Nobody approves their own item except a Manager."),
          FIG("p6_ks_rev", "The Review queue.", maxh=150),
          STEPS(["Open the item from the queue and read it.",
                 "Check the equipment set, the facts and the caution.",
                 "Select **Approve** to publish the item, or **Reject** and give a reason. The reason goes into the history.",
                 "For answer feedback, select **Create knowledge item** to start a correction, or **Mark reviewed** if no change is needed."]),
          H2("Quality gates"),
          P("The Quality gates tab runs checks on the knowledge base: drafts older than 14 days, items in review longer than 7 days, items without a linked asset or tags, approved items that cannot be found by their own title and open answer feedback. Each check shows a result and a pass or fail status. A second table shows the baseline data quality of the source documents."),
          FIG("p6_ks_qg", "Quality gates.", maxh=160),
          H2("Question log"),
          P("The Question log lists the questions asked of the assistant, with the role of the person, the handler, the confidence, the response time, the number of sources cited and the feedback. The last 500 are kept in the browser. Use **Export JSONL** or **Export CSV** to save them."),
          FIG("p6_ks_qa", "The Question log.", maxh=130),
          H2("Audit trail"),
          P("The audit trail records every change: when, who, the role, the action, the detail and the item. Use **Export CSV** to save it. Chapter 40 describes what is recorded."),
          FIG("p6_ks_au", "The Audit trail.", maxh=150),
          ]
    # ------------------------------------------------------------------ 35 Data Quality
    b += [H1(35, "Data Quality", ["Engineer", "Reliability", "HSE", "Manager"], PART6,
             "Data Quality lists the inconsistencies and gaps found while the knowledge base was built. Each issue has a severity, a source and a suggested action."),
          FIG("p6_quality", "The Data Quality page.",
              [(1, "**Issues by severity**: high, medium and info.", "^Issues by severity$"),
               (2, "**Issues by source**. Select a bar to filter.", "^Issues by source$"),
               (3, "Filters for severity and status. **Export register (CSV)** saves the list.", "^Export register"),
               (4, "The issue table: source, issue, severity, suggested action and status.", "^Source$"),
               (5, "**Mark resolved** and **Accept as is** for each issue.", "^Mark resolved")], maxh=210),
          STEPS(["Filter by severity to start with the high issues.",
                 "Read the issue and the suggested action. For example, a drawing title that says KA-4501 when the body says KC-4501 is shown with the suggestion to use KC-4501 and to add KA-4501 as an alias.",
                 "Correct the source, then select **Mark resolved**. If the difference is acceptable, select **Accept as is**.",
                 "Select **Export register (CSV)** to share the register."]),
          NOTE("caution", "Resolve or accept every issue before you treat the knowledge as approved. The Dashboard counts the open issues."),
          ]
    # ------------------------------------------------------------------ 36 Integrations
    b += [H1(36, "Integrations and the knowledge graph", ["Engineer", "Reliability", "Manager"], PART6,
             "The Integrations page shows how the platform connects to the systems the company already uses, and how its data is organised."),
          FIG("p6_int", "The Integrations and Architecture page.",
              [(1, "The seven tabs.", "^Connectors$"),
               (2, "A notice states that the connectors are simulated.", "^SIMULATED"),
               (3, "One tile for each system: EDMS, AIMS, CMMS and HIST.", "^EDMS$"),
               (4, "Endpoint, authentication and refresh settings, with **Test connection** and **Sync now**.", "^Test connection$"),
               (5, "**Field mapping** from the source fields to the hub data model.", "^Field mapping")], maxh=210),
          TABLE(["Tab", "Use"],
                [["Connectors", "Configure a connection to the document system (EDMS), the asset register (AIMS), the maintenance system (CMMS) and the historian (HIST)"],
                 ["Data model", "Read the entities and fields of the hub data model"],
                 ["Architecture", "See how the page, the shared database and the AI service fit together"],
                 ["AI provider contract", "Read what the platform sends to an AI service and what it expects back"],
                 ["Backend bundle", "Read the specification for the production backend"],
                 ["Usage and quality", "See the use of the assistant and the results of the evaluation questions"],
                 ["Knowledge graph", "See the records linked to an asset"]],
                [24, 76]),
          NOTE("note", "The connectors in this version are simulated. They show the configuration and the field mapping, and they test and sync against the built-in data."),
          FIG("p6_int_model", "The Data model tab.", maxh=140),
          FIG("p6_int_arch", "The Architecture tab.", maxh=170),
          H2("Knowledge graph"),
          FIG("p6_int_graph", "The Knowledge graph.",
              [(1, "Node types: asset, document, instrument, interlock, one point lesson, breakdown work order and user knowledge.", "^Asset$"),
               (2, "Each node is a record linked to the asset by its equipment tag. Select one to open it.", "^Each node is a record")], maxh=200),
          ]
    return b
